// Extracts { slug, title } of the hardcoded static blogs from src/pages/Blogs.tsx
// into a small generated file, so the CMS "Related in this series" picker can
// search and link them by title (not just CMS blogs). Runs at build time.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SRC = path.join(ROOT, "src", "pages", "Blogs.tsx");
const OUT = path.join(ROOT, "src", "data", "staticBlogsIndex.ts");

let src = "";
try {
  src = readFileSync(SRC, "utf8");
} catch {
  console.warn("[gen-static-index] Blogs.tsx not found — skipping");
  process.exit(0);
}

// Only scan the BLOG_POSTS array (avoids RELATED_SERIES keys, FAQ, etc.)
const start = src.indexOf("const BLOG_POSTS");
const body = start >= 0 ? src.slice(start) : src;

// Each post is `{ id: N, slug: "…", …, title: "…", … }` — grab each slug then
// the nearest standalone `title:` after it (\btitle avoids matching metaTitle).
const re = /\bslug:\s*"([^"]+)"[\s\S]*?\btitle:\s*"((?:[^"\\]|\\.)*)"/g;
const seen = new Set();
const out = [];
let m;
while ((m = re.exec(body))) {
  const slug = m[1];
  const title = m[2].replace(/\\"/g, '"').replace(/\\n/g, " ");
  if (!seen.has(slug)) {
    seen.add(slug);
    out.push({ slug, title });
  }
}

mkdirSync(path.dirname(OUT), { recursive: true });
writeFileSync(
  OUT,
  "// AUTO-GENERATED by scripts/gen-static-index.mjs — do not edit by hand.\n" +
    "// Slug + title of the hardcoded static blogs, for the CMS Related picker search.\n" +
    `export const STATIC_BLOG_INDEX: { slug: string; title: string }[] = ${JSON.stringify(out, null, 2)};\n`,
  "utf8"
);
console.log(`[gen-static-index] wrote ${out.length} static blogs`);
